"""Generated bytecode must not enter a fresh bundle or its copy traversal."""
import importlib.util
from pathlib import Path

import pytest


TOOL = Path(__file__).resolve().parents[1] / "tools" / "build_bundle.py"
SPEC = importlib.util.spec_from_file_location("bundle_cache_under_test", TOOL)
assert SPEC is not None and SPEC.loader is not None
bundle = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(bundle)


@pytest.mark.parametrize("kind", ["runtime", "tidal", "sonos", "apple_music"])
def test_fresh_python_payload_excludes_cache_without_touching_input(tmp_path, kind):
    source = tmp_path / "input"
    source.mkdir()
    target = tmp_path / "bundle"
    runtime_site = target / "runtime" / "Lib" / "site-packages"
    if kind == "runtime":
        (source / "python.exe").write_bytes(b"synthetic-runtime")
        (source / "python314.zip").write_bytes(b"immutable-stdlib-archive")
        roots = [source]
    else:
        runtime_site.mkdir(parents=True)
        if kind == "tidal":
            packages = bundle.TIDAL_TEST_PACKAGES
            shared = bundle.TIDAL_SHARED_METADATA
        elif kind == "sonos":
            packages = bundle.SONOS_LOCAL_TEST_PACKAGES
            shared = bundle.SONOS_LOCAL_SHARED_METADATA
        else:
            packages = bundle.APPLE_MUSIC_TEST_PACKAGES
            shared = ()
        for name in shared:
            (runtime_site / name).mkdir()
        roots = []
        for names in packages.values():
            for name in names:
                item = source / name
                if name.endswith(".py"):
                    item.write_text("# module\n", encoding="utf-8")
                else:
                    item.mkdir()
                    (item / "METADATA").write_text("fixture\n", encoding="utf-8")
                    roots.append(item)

    for root in roots:
        (root / "module.py").write_text("value = 1\n", encoding="utf-8")
        (root / "extension.pyd").write_bytes(b"synthetic-extension")
        cache = root / "nested" / "__pycache__"
        cache.mkdir(parents=True)
        (cache / "RegisterForGameControllerEventsMessage_pb2.cpython-314.pyc").write_bytes(b"cache")
        (cache / "other-file").write_bytes(b"not-payload")
        (root / "legacy.pyc").write_bytes(b"legacy-cache")
        (root / "legacy.pyo").write_bytes(b"legacy-cache")
    before = {p.relative_to(source): p.read_bytes() for p in source.rglob("*") if p.is_file()}

    if kind == "runtime":
        copied = bundle.copy_runtime(target, source)
        output_roots = [target / "runtime"]
    else:
        function = {
            "tidal": bundle.copy_tidal_test_dependencies,
            "sonos": bundle.copy_sonos_local_dependencies,
            "apple_music": bundle.copy_apple_music_dependencies,
        }[kind]
        copied = function(target, bundle.profile_from_id("test"), source)
        output_roots = [runtime_site / root.name for root in roots]

    for root in output_roots:
        assert (root / "module.py").read_text(encoding="utf-8") == "value = 1\n"
        assert (root / "extension.pyd").read_bytes() == b"synthetic-extension"
    if kind == "runtime":
        assert (target / "runtime" / "python314.zip").read_bytes() == b"immutable-stdlib-archive"
    actual = [p.relative_to(target).as_posix() for p in target.rglob("*") if p.is_file()]
    assert not any("__pycache__" in Path(name).parts or name.endswith((".pyc", ".pyo")) for name in actual)
    assert not any("__pycache__" in Path(name).parts or name.endswith((".pyc", ".pyo")) for name in copied)
    assert before == {p.relative_to(source): p.read_bytes() for p in source.rglob("*") if p.is_file()}
